import collections
import functools

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    if maxsize is None:
        return functools.lru_cache(maxsize, typed)

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.access_count = collections.defaultdict(int)
            self.order = []

        def __call__(self, *args):
            if self.typed:
                key = (args, type(args))
            else:
                key = args

            if key in self.cache:
                self.access_count[key] += 1
                self.order.remove(key)
                self.order.append(key)
                return self.cache[key]

            if len(self.cache) >= self.maxsize:
                lfu_key = self.order[0]
                for k in self.order:
                    if self.access_count[k] < self.access_count[lfu_key]:
                        lfu_key = k
                del self.cache[lfu_key]
                del self.access_count[lfu_key]
                self.order.remove(lfu_key)

            result = self.cache[key] = self.func(*args)
            self.access_count[key] += 1
            self.order.append(key)
            return result

        def cache_info(self):
            return functools.cache_info(hits=len(self.cache), misses=0, maxsize=self.maxsize, currsize=len(self.cache))

        def cache_clear(self):
            self.cache.clear()
            self.access_count.clear()
            self.order.clear()

    def decorating_function(func):
        lfu = LFUCache(maxsize, typed)
        lfu.func = func
        functools.update_wrapper(lfu, func)
        return lfu

    return decorating_function
