from typing import Dict, Any
import json
from xml.etree import ElementTree as ET

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # Try to parse as JSON
        data = json.loads(document)
        if 'subject' in data and 'links' in data:
            return data
    except json.JSONDecodeError:
        pass

    # If JSON parsing fails, try to parse as XRD (XML)
    try:
        root = ET.fromstring(document)
        if root.tag.endswith('XRD'):
            subject = root.find('{*}Subject')
            links = []
            for link in root.findall('{*}Link'):
                link_data = {attr.tag.split('}')[1]: attr.text for attr in link}
                links.append(link_data)
            return {'subject': subject.text if subject is not None else None, 'links': links}
    except ET.ParseError:
        pass

    raise ValueError("Invalid webfinger document format")
